#!/usr/bin/env python3
"""Verify the fictional two-page PDF generated by Android's camera unit test.

Uses an isolated database, local OCR and in-process HTTP. No cloud or real cases.
"""
import hashlib,json,os,sys,tempfile,time
from pathlib import Path
root=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(root/'backend'))
source=root/'android/app/build/native-previews/camera-two-pages.pdf'
if not source.is_file(): raise SystemExit('Run npm run android:build first to generate the fictional camera fixture.')
from cryptography.fernet import Fernet
from pypdf import PdfReader
from fastapi.testclient import TestClient
with tempfile.TemporaryDirectory(prefix='docket-camera-api-') as temporary:
    os.environ.update({'DATABASE_PATH':str(Path(temporary)/'verify.sqlite3'),'DATABASE_URL':'','DOCKET_ENV':'development','DOCKET_DEMO_MODE':'1','GEMINI_API_KEY':'','OCR_PROVIDER':'local','CLAMAV_HOST':'','DATA_ENCRYPTION_KEY':Fernet.generate_key().decode()})
    os.environ.pop('DB_HOST',None)
    from app.main import app
    content=source.read_bytes();pdf=PdfReader(source,strict=True)
    assert len(pdf.pages)==2 and all(len(page.images)==1 for page in pdf.pages)
    started=time.perf_counter()
    with TestClient(app) as client:
        before=len(client.get('/api/notices').json())
        preview=client.post('/api/ocr/ingest-and-triage',files={'file':('camera-notice.pdf',content,'application/pdf')})
        assert preview.status_code==200,preview.status_code
        analysis=preview.json();text=analysis['structured_triage']['full_markdown_transcript']
        assert analysis['page_count']==2
        assert text.index('PAGE TWO')<text.index('PAGE ONE')
        assert set(analysis['structured_triage']['detected_languages'])=={'English','Hindi'}
        assert len(client.get('/api/notices').json())==before
        created=client.post('/api/notices/analyze',files={'file':('camera-notice.pdf',content,'application/pdf')},data={'date_of_issue':'2026-10-15','date_of_service':'2026-10-15','window_days':'15','ocr_language':'auto'})
        assert created.status_code==200,created.status_code
        assert created.json()['ocr_report']['page_count']==2
        assert created.json()['ocr_report']['requested_languages']=='auto'
        assert len(client.get('/api/notices').json())==before+1
    result={'scope':'Fictional Android-generated two-page PDF, isolated in-process API and local OCR only','pdf_strict_parse':True,'pages':2,'embedded_jpeg_images':2,'page_order_verified':True,'bilingual_detection_verified':True,'preview_creates_no_case':True,'one_upload_creates_one_case':True,'elapsed_ms':round((time.perf_counter()-started)*1000),'sha256':hashlib.sha256(content).hexdigest(),'physical_camera_tested':False,'live_cloud_ocr_tested':False}
    target=root/'output/ocr/camera-capture-verification.json';target.write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(result,indent=2))
